examples.template:
VStack {
    ScrollView {
        LazyVStack(alignment: .leading, spacing: theme.spacing.space2) {
            ForEach(0..<{{count}}, id: \.self) { index in
                Text(lines[index % lines.count])
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textDefault)
                    .id(index)
            }
        }
        .scrollTargetLayout()
        .frame(maxWidth: .infinity, alignment: .leading)
    }
    .scrollPosition(id: $position, anchor: .bottom)
    .defaultScrollAnchor(.bottom)
    .frame(height: theme.spacing.space24 * 2)
    if position != {{count}} - 1 {
        MonarchButton({{jump}}, size: .sm) {
            withAnimation { position = {{count}} - 1 }
        }
    }
}
.padding(.horizontal)

